import {lessons,phrases,scenarios,pronunciation,alphabet,combinations,phases,exam,officialLinks,LEVELS,PAPERS,notes} from './content.mjs';
import {ranks,rankFor,points,badges,unlockBadges} from './rewards.mjs';
import {chooseVoice,rankedVoices,voiceQuality,NATURAL_RATE,SLOW_RATE,LOCALE,recordingFor,createSpeechPlayer} from './voice.mjs';
import {STORAGE_KEY,dayKey,initialState,validateState,schedule,dueCards,upToLevel,streak,daysUntil,bestMatch,wordCount,scoreAnswers,logActivity,validDay} from './core.mjs';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',book:'<path d="M12 5v16m0-16C8 2 3 4 3 4v15s5-2 9 2c4-4 9-2 9-2V4s-5-2-9 1Z"/>',cards:'<rect x="5" y="5" width="15" height="16" rx="2"/><path d="M16 2H4a2 2 0 0 0-2 2v13m7-8h7m-7 4h5"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l1-5A9 9 0 1 1 21 11Z"/><path d="M8 10h8m-8 4h5"/>',chart:'<path d="M3 3v18h18M8 16v-5m5 5V7m5 9V4"/>',settings:'<path d="m9 3 1-1h4l1 3 3 1 3 1-1 4 1 2-1 4-3 1-2 3h-4l-2-3-3-1-3-1 1-4-1-2 1-4 3-1Z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',flame:'<path d="M12 2c1 5-4 7-2 10 3-1 4-4 4-4 5 4 7 12-2 14-9-2-8-10-4-14-1 3 0 4 0 4-1-5 4-7 4-10Z"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',play:'<path d="m8 3 13 9-13 9Z"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m8.5 14-1.5 8 5-3 5 3-1.5-8"/>',pen:'<path d="M4 20h4L19 9l-4-4L4 16Z"/><path d="m13 7 4 4"/>',ear:'<path d="M7 9a5 5 0 0 1 10 0c0 4-4 4-4 8a3 3 0 0 1-6 0"/><path d="M10 9a2 2 0 0 1 4 0"/>',alpha:'<path d="M18 6c-1 6-2 12 1 12M17 12c-1-4-3-6-6-6-3 0-5 3-5 6s2 6 5 6c3 0 5-3 6-6Z"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;}
$$('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
const main=$('#main');let state=initialState(),storageProblem=false;
try{const s=localStorage.getItem(STORAGE_KEY);if(s)state=validateState(JSON.parse(s));}catch{storageProblem=true;}
function save(){const won=rewardCheck();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{if(!storageProblem)toast('Device storage is unavailable. Export a backup to keep this session.');storageProblem=true;}updateChrome();if(won)setTimeout(()=>party(won),450);}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4800);}
// Rewards: a new rank beats new badges, which beat the daily goal, so one save shows one celebration.
const name=()=>state.settings.name||'Sana';
const greekName=()=>/^sana$/i.test(name())?'Σάνα':name();
const praise=()=>{const list=['Μπράβο, πριγκίπισσα!',`Μπράβο, ${greekName()}!`,'Τέλεια! ✨','Υπέροχα! 💖','Εξαιρετικά! 🌸','Πολύ καλά, αγάπη μου!'];return list[Math.floor(Math.random()*list.length)];};
let lastRank=rankFor(points(state)).index;
function rewardCheck(){let won=null;
 if(state.goalDay!==dayKey()&&todayMinutes()>=state.settings.goal){state.goalDay=dayKey();won={emoji:'🎯',eyebrow:'DAILY GOAL REACHED',title:`${state.settings.goal} minutes today, ${name()}!`,text:'That’s your goal for today. Anything more is pure sparkle.'};}
 const fresh=unlockBadges(state,dayKey()),rank=rankFor(points(state));
 if(fresh.length)won={emoji:fresh[0].emoji,eyebrow:fresh.length>1?`${fresh.length} NEW BADGES`:'NEW BADGE',title:fresh.length>1?fresh.map(b=>b.emoji).join(' '):fresh[0].title,text:fresh.length>1?fresh.map(b=>b.title).join(' · '):fresh[0].desc+'. Μπράβο, πριγκίπισσα!',link:'#progress'};
 if(rank.index>lastRank)won={emoji:rank.emoji,eyebrow:'YOU WERE CROWNED',title:rank.title,text:`${rank.el} · ${points(state)} points. Your Greek is growing, ${name()}.`,el:rank.el,link:'#progress'};
 lastRank=rank.index;return won;}
const calm=()=>window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
// Little emoji particles fly out from a point (or rain from the top of the screen).
function burst(x,y,count=14,set=['💖','✨','🌸','💗','⭐']){if(calm())return;const layer=document.createElement('div');layer.className='burst-layer';layer.setAttribute('aria-hidden','true');
 for(let i=0;i<count;i++){const p=document.createElement('span'),angle=Math.random()*Math.PI*2,dist=50+Math.random()*90;p.textContent=set[i%set.length];p.style.left=x+'px';p.style.top=y+'px';p.style.setProperty('--dx',Math.cos(angle)*dist+'px');p.style.setProperty('--dy',Math.sin(angle)*dist-40+'px');p.style.setProperty('--r',(Math.random()*120-60)+'deg');p.style.animationDelay=Math.random()*80+'ms';layer.append(p);}
 document.body.append(layer);setTimeout(()=>layer.remove(),1400);}
function burstFrom(el,count){if(!el)return;const r=el.getBoundingClientRect();burst(r.left+r.width/2,r.top+r.height/2,count);}
function rain(count=36){if(calm())return;const layer=document.createElement('div');layer.className='rain-layer';layer.setAttribute('aria-hidden','true');const set=['💖','👑','✨','🌸','💗','🎀','⭐','🦋'];
 for(let i=0;i<count;i++){const p=document.createElement('span');p.textContent=set[i%set.length];p.style.left=Math.random()*100+'vw';p.style.fontSize=16+Math.random()*18+'px';p.style.animationDuration=2.2+Math.random()*1.8+'s';p.style.animationDelay=Math.random()*.9+'s';p.style.setProperty('--sway',(Math.random()*80-40)+'px');layer.append(p);}
 document.body.append(layer);setTimeout(()=>layer.remove(),5200);}
function party({emoji,eyebrow,title,text,el,link}){rain();const d=$('#party');d.innerHTML=`<div class="party-card"><div class="party-emoji">${emoji}</div><p class="eyebrow">${esc(eyebrow)}</p><h2>${esc(title)}</h2>${el?`<p class="party-el" lang="el">${esc(el)}</p>`:''}<p>${esc(text)}</p><div class="button-row" style="justify-content:center">${link?`<a class="btn secondary small" href="${link}" data-action="close-party">See my crowns</a>`:''}${action('Yay! 💖','close-party','primary small')}</div></div>`;d.classList.add('visible');clearTimeout(party.timer);party.timer=setTimeout(()=>d.classList.remove('visible'),7000);}
const nav=[['today','home','Today'],['lessons','book','Learn'],['review','cards','Review'],['practice','mic','Speak'],['exam','award','Exam'],['phrases','chat','Phrasebook'],['progress','chart','Progress']];
const paperIcons={reading:'book',listening:'ear',writing:'pen',speaking:'mic'};
let route='',sub='',quiz=null,review=null,speakIndex=0,scenarioSession=null,examSession=null,examTimer=null,writingTimer=null,recognition=null,recording=null,recordTimeout,recordUrl='',recordStream=null,voices=[],installPrompt=null,sessionSpoken=new Set();
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
let voicePack={version:1,locale:LOCALE,clips:{}};
const hasRecordings=()=>Object.keys(voicePack.clips).length>0;
const level=()=>state.settings.level;
const activePhrases=()=>upToLevel(phrases,level());
function selectedVoice(){return chooseVoice(voices,state.settings.voice);}
const player=createSpeechPlayer({synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,AudioClass:window.Audio,onError:toast,onFallback:()=>toast('That recording could not load. Trying your device voice.')});
function loadVoices(){voices=window.speechSynthesis?.getVoices()||[];updateVoiceStatus();if(route==='settings')renderVoiceOptions();}
function updateVoiceStatus(){
 const v=selectedVoice(),recorded=hasRecordings()&&state.settings.audioSource!=='device';
 $$('[data-voice-status]').forEach(n=>{n.className=`notice ${recorded||v?'':'warn'}`;
 n.innerHTML=recorded?`${icon('volume')} <span>Greek recordings included · AI-generated voice. <a href="#settings">Audio settings</a></span>`:v?`${icon('volume')} <span>${esc(v.name)} · ${esc(v.lang)} · ${esc(voiceQuality(v))}. <a href="#settings">Audio settings</a></span>`:'No Greek voice has loaded on this device yet. <a href="#settings">Set up your listening voice →</a>';
 });
}
function say(text,slow=false,button=null){
 loadVoices();
 const forceDevice=button?.dataset.deviceVoice==='true';
 const clip=!forceDevice&&state.settings.audioSource!=='device'?recordingFor(voicePack,text):null;
 player.play(text,{voice:selectedVoice(),rate:slow?SLOW_RATE:state.settings.rate,clip,onState:playing=>button?.classList.toggle('is-playing',playing)});
}
// Long listening scripts are spoken sentence by sentence: some browsers cut off long utterances.
function sayAll(lines,button=null){
 loadVoices();const parts=lines.flatMap(l=>l.split(/(?<=[.;!·])\s+/)).filter(Boolean);let i=0;
 const next=()=>{if(i>=parts.length){button?.classList.remove('is-playing');return;}const text=parts[i++];player.play(text,{voice:selectedVoice(),rate:state.settings.rate,clip:state.settings.audioSource!=='device'?recordingFor(voicePack,text):null,onState:p=>button?.classList.toggle('is-playing',p),onEnd:()=>setTimeout(next,350)});};
 next();
}
function setPlaybackRate(rate){state.settings.rate=rate;save();const slider=$('#speech-rate'),output=$('#speed-value');if(slider)slider.value=rate;if(output)output.textContent=rate.toFixed(2)+'×';$$('[data-action="playback-preset"]').forEach(b=>{const active=Number(b.dataset.rate)===rate;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
async function loadVoicePack(){try{const response=await fetch('./audio/manifest.json',{cache:'no-cache'});if(!response.ok)return;const pack=await response.json();if(pack.version!==1||pack.locale!==LOCALE||!pack.clips||typeof pack.clips!=='object')return;voicePack=pack;if(route==='settings')settingsPage();else updateVoiceStatus();}catch{}}
function sound(el,slow=false,label='Listen'){return `<button class="sound-btn" data-say="${encodeURIComponent(el)}" ${slow?'data-slow="true"':''} aria-label="${esc(label)}: ${esc(el)}">${icon('volume')}</button>`;}
function listenButton(el,slow=false,label='Listen'){return `<button class="btn secondary small" data-say="${encodeURIComponent(el)}" ${slow?'data-slow="true"':''}>${icon('volume')}${esc(label)}</button>`;}
function action(label,id,style='primary',extra=''){return `<button class="btn ${style}" data-action="${id}" ${extra}>${label}</button>`;}
function heading(title,subtitle='',eyebrow='YOUR GREEK JOURNEY',side=''){return `<div class="page-intro"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${side}</div>`;}
function tr(text){return state.settings.translit&&text?`<span class="tr">${esc(text)}</span>`:'';}
function levelBadge(l){return `<span class="level-badge level-${l.toLowerCase()}">${l}</span>`;}
function sourceNote(){return `<p class="source-note">Lessons follow the A1 and A2 levels of the Common European Framework, as used by the Greek Language Certificate (Πιστοποίηση Ελληνομάθειας). Transliterations are a reading aid; aim to read the Greek itself as soon as you can. Practice papers are original and only follow the official formats. Official samples: <a href="${officialLinks.samples}" target="_blank" rel="noopener">greek-language.gr</a>.</p>`;}
function totalPoints(){return Object.values(state.activity).reduce((sum,a)=>sum+a.points,0);}
function todayMinutes(){return state.activity[dayKey()]?.minutes||0;}
function reviewedCount(){return Object.keys(state.cards).filter(id=>phrases.some(p=>p.id===id)).length;}
function completedCount(list=lessons){return list.filter(l=>state.completed[l.id]).length;}
function nextLesson(){const list=upToLevel(lessons,level());return list.find(l=>!state.completed[l.id])||lessons.find(l=>!state.completed[l.id])||lessons[0];}
function nextPaper(){return PAPERS.find(p=>!state.exam[`${level()}-${p}`])||'reading';}
function updateChrome(){const active=route==='lesson'||route==='alphabet'?'lessons':route==='scenario'?'practice':route==='paper'?'exam':route;
 $('#nav').innerHTML=nav.map(([id,i,label])=>`<a class="nav-link ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}${id==='review'?`<span class="badge">${dueCards(activePhrases(),state).length}</span>`:''}</a>`).join('');
 $('#mobile-nav').innerHTML=nav.slice(0,5).map(([id,i,label])=>`<a class="${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');
 $('#streak-chip').innerHTML=`${icon('flame')} ${streak(state.activity)} day streak`;
 const days=daysUntil(state.settings.examDate);
 $('#sidebar-exam').textContent=days===null?'Set your exam date in Settings':`${new Date(state.settings.examDate+'T12:00:00').toLocaleDateString('en',{day:'numeric',month:'long',year:'numeric'})}`;
 $('#sidebar-level').textContent=`Goal: ${level()} certificate`;
}
function examChip(){const days=daysUntil(state.settings.examDate);return `<a class="trip-chip" href="#settings">🇬🇷 ${days===null?'<strong>Set your exam date</strong>':`<strong>${days} days</strong> to your ${level()} exam`} ${icon('arrow')}</a>`;}
function illustration(){return `<svg viewBox="0 0 420 350" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="An illustrated Greek island with white houses, a crowned blue dome, floating hearts and the sea"><circle cx="300" cy="95" r="52" fill="#f4d47e"/><g stroke="#e3c46d" stroke-width="1.3"><path d="M300 25v-10M300 175v-10M230 95h-10M380 95h-10"/></g><path d="M0 250c70-20 140-25 210-12s140 10 210-8v120H0Z" fill="#2f6fa3"/><path d="M0 285c80-14 150-10 220 2s130 8 200-6v69H0Z" fill="#1f5584"/><g stroke="#cfe3f3" stroke-width="2" fill="none" stroke-linecap="round" opacity=".7"><path d="M40 300q15-6 30 0t30 0M250 315q15-6 30 0t30 0M150 330q15-6 30 0t30 0"/></g><path d="M40 252V170h70v82Z" fill="#fbfbf7"/><path d="M110 252v-60h65v60Z" fill="#f1f2ee"/><path d="M175 248V150h80v98Z" fill="#fbfbf7"/><path d="M185 150a30 30 0 0 1 60 0Z" fill="#2c6aa0"/><path d="M255 246v-58h55v58Z" fill="#f1f2ee"/><g fill="#2c6aa0"><path d="M58 190h14v18H58Zm22 0h14v18H80ZM130 206h12v16h-12ZM200 180h12v20h-12Zm20 0h12v20h-12ZM272 202h12v16h-12Z"/><path d="M68 228h16v24H68Z"/><path d="M207 222h16v26h-16Z"/></g><path d="M36 170h78M106 192h73M251 188h63" stroke="#d9dcd3" stroke-width="3"/><g fill="#7d965e"><path d="M330 250c-2-30 6-48 10-50 4 2 10 20 6 50Z"/></g><path d="M340 205v45" stroke="#5f7448" stroke-width="2"/><g fill="#fff" opacity=".85"><path d="M60 60q10-10 22 0q12-8 20 4H55q-2-4 5-4Z"/><path d="M140 40q8-8 18 0q10-6 16 3h-38q0-3 4-3Z"/></g><g><path class="float-heart" style="animation-delay:0s" transform="translate(120 95) scale(1.6)" d="M0 4C0-1 7-1 7 4C7-1 14-1 14 4C14 9 7 13 7 13C7 13 0 9 0 4Z" fill="#f08bb4"/><path class="float-heart" style="animation-delay:1.2s" transform="translate(360 160) scale(1.2)" d="M0 4C0-1 7-1 7 4C7-1 14-1 14 4C14 9 7 13 7 13C7 13 0 9 0 4Z" fill="#f6a9c9"/><path class="float-heart" style="animation-delay:2.1s" transform="translate(250 60) scale(1)" d="M0 4C0-1 7-1 7 4C7-1 14-1 14 4C14 9 7 13 7 13C7 13 0 9 0 4Z" fill="#e86a9e"/><path class="float-heart" style="animation-delay:0.6s" transform="translate(60 120) scale(1.1)" d="M0 4C0-1 7-1 7 4C7-1 14-1 14 4C14 9 7 13 7 13C7 13 0 9 0 4Z" fill="#f6a9c9"/></g><path class="crown-dome" d="M202 121l-4-15 9 6 8-11 8 11 9-6-4 15Z" fill="#f4c64e"/></svg>`;}
function greeting(){const h=new Date().getHours();return h<12?'Καλημέρα':'Καλησπέρα';}
function dayOfYear(){const d=new Date();return Math.floor((d-new Date(d.getFullYear(),0,0))/864e5);}
function rankCard(){const pts=points(state),r=rankFor(pts),minutes=todayMinutes(),goal=Math.min(1,minutes/state.settings.goal);
 return `<a class="rank-card" href="#progress"><div class="goal-ring" style="--p:${goal}"><span>${r.emoji}</span></div><div class="rank-copy"><p class="eyebrow">YOUR CROWN</p><h3>${esc(r.title)}</h3><p class="rank-el" lang="el">${esc(r.el)}</p><div class="sparkle-track"><span style="width:${r.progress*100}%"></span></div><small>${r.next?`${pts} points · ${r.next.min-pts} to ${esc(r.next.title)} ${r.next.emoji}`:`${pts} points · the highest crown 👑`}</small><small>${goal>=1?'🎯 Daily goal done!':`🎯 ${Math.round(minutes)} / ${state.settings.goal} minutes today`} · ${Object.keys(state.badges).length} / ${badges.length} badges</small></div></a>`;}
function loveNote(){const n=notes[dayOfYear()%notes.length];
 return `<section class="love-note" data-action="open-note" role="button" tabindex="0" aria-label="Open today’s note"><div class="envelope" aria-hidden="true">💌</div><div class="note-closed"><p class="eyebrow">A LITTLE NOTE FOR YOU</p><h3>Tap to open, princess</h3></div><div class="note-open"><p class="eyebrow">TODAY’S NOTE 💗</p><blockquote lang="el">${esc(n.el)}</blockquote>${tr(n.tr)}<p>${esc(n.en)}</p><p class="note-fr" lang="fr">${esc(n.fr)}</p>${sound(n.el)}</div></section>`;}
function todayPage(){const next=nextLesson(),list=upToLevel(lessons,level()),count=completedCount(list),due=dueCards(activePhrases(),state).length,paper=nextPaper();const phrase=phrases[new Date().getDate()%phrases.length];const date=new Date().toLocaleDateString('en',{weekday:'long',day:'numeric',month:'long'});
 main.innerHTML=heading(`<span lang="el">${greeting()}, πριγκίπισσα!</span> <span class="wave">👑</span>`,`A little Greek today, ${esc(name())}? Every step brings the certificate closer.`,date.toUpperCase(),examChip())+`<div class="personal-row">${rankCard()}${loveNote()}</div><section class="hero"><div class="hero-copy"><span class="pill"><i></i> ${esc(name().toUpperCase())}’S ${level()} CERTIFICATE PATH</span><h2 lang="el">Λίγα ελληνικά<br><em>κάθε μέρα.</em></h2><p>You already live in Greek every day, ${esc(name())}. Now we make it official: clear grammar, reading and writing, and practice for every paper of the Greek Language Certificate. Every step earns points, badges and a new crown.</p><a href="#lesson/${next.id}" class="btn primary">${count?'Continue learning':'Start your first lesson'} ${icon('arrow')}</a><div class="hero-footnote">${icon('clock')} ${state.settings.goal} minutes a day adds up.</div></div><div class="hero-art">${illustration()}</div></section>
 <div class="stats-row"><a href="#progress" class="stat"><span class="stat-icon">${icon('flame')}</span><div><strong>${streak(state.activity)} <span style="font-size:12px">${streak(state.activity)===1?'day':'days'}</span></strong><small>Your learning streak</small></div></a><a href="#review" class="stat"><span class="stat-icon">${icon('cards')}</span><div><strong>${reviewedCount()}</strong><small>Phrases you’ve reviewed</small></div></a><a href="#lessons" class="stat"><span class="stat-icon">${icon('book')}</span><div><strong>${count}<span style="font-size:12px;color:var(--muted)"> / ${list.length}</span></strong><small>Lessons up to ${level()}</small></div></a></div>
 <section><div class="section-heading"><h2>Today’s plan</h2><span>Your ${state.settings.goal}-minute daily goal.</span></div><div class="daily-grid">${[[`lesson/${next.id}`,'Learn something new',next.title,`${next.level} LESSON`,'5 min'],['review','Make it stick',`${due} phrases ready for review`,'SPACED REPETITION','5 min'],[`paper/${level()}-${paper}`,'Exam practice',`${level()} ${exam[level()].papers[paper].title.toLowerCase()} paper`,'CERTIFICATE FORMAT','10 min']].map(([url,title,desc,tag,time],i)=>`<a class="task-card" href="#${url}"><div class="task-top"><span class="task-number">0${i+1}</span><span class="task-time">${icon('clock')}${time}</span></div><h3>${title}</h3><p>${esc(desc)}</p><div class="task-bottom"><span class="task-tag">${tag}</span><span class="arrow-circle">${icon('arrow')}</span></div></a>`).join('')}</div></section>
 <div class="lower-grid"><section class="phrase-feature"><p class="eyebrow">A PHRASE FOR TODAY</p><blockquote lang="el">${esc(phrase.el)}</blockquote>${tr(phrase.tr)}<p>${esc(phrase.en)}</p>${sound(phrase.el)}<a class="text-link" href="#phrases">Explore your phrasebook ${icon('arrow')}</a></section><section class="route-panel"><p class="eyebrow">STEP BY STEP</p><h3>On your way to ${level()}</h3><div class="progress-track"><span style="width:${count/list.length*100}%"></span></div><div class="progress-label"><span>${count} of ${list.length} lessons complete</span><a href="#progress" class="text-link">Your progress ${icon('arrow')}</a></div><div class="route-steps">${phases.map((p,i)=>`<div class="route-step ${i===Math.min(3,Math.floor(completedCount()/lessons.length*4))?'active':''}"><span>${i+1}</span>${esc(p.title)}</div>`).join('')}</div></section></div>${storageProblem?'<div class="notice warn">Storage is unavailable or a saved file could not be read. Export your progress from Settings to keep a backup.</div>':''}`;
}
