function lessonsPage(){main.innerHTML=heading('Small lessons. Real Greek.','From the alphabet to formal emails, in short steps.','LEARN AT YOUR PACE',`<span class="trip-chip">${completedCount()} / ${lessons.length} complete</span>`)+`<a class="panel alphabet-link" href="#alphabet"><span class="alphabet-sample" lang="el">Αα Ββ Γγ</span><div><p class="eyebrow">START HERE</p><h2>The Greek alphabet</h2><p>Hear all 24 letters, the letter pairs and the stress mark.</p></div>${icon('arrow')}</a>${LEVELS.map(lv=>{const list=lessons.filter(l=>l.level===lv);return `<section class="level-group"><div class="section-heading"><h2>${levelBadge(lv)} ${esc(exam[lv].name)}</h2><span>${completedCount(list)} / ${list.length} complete</span></div><div class="lesson-list">${list.map(lessonCard).join('')}</div></section>`;}).join('')}`+sourceNote();}
