function renderQuiz(){const l=lessons.find(l=>l.id===quiz.id),q=l.questions[quiz.index];if(!q)return finishQuiz();main.innerHTML=`<div class="lesson-body"><a class="text-link back-link" href="#lesson/${l.id}">${icon('back')} Back to lesson</a>${heading('Put it into practice.',esc(l.title),'A QUICK CHECK')}<div class="quiz-progress"><span>Question ${quiz.index+1} of ${l.questions.length}</span><div class="progress-track"><span style="width:${quiz.index/l.questions.length*100}%"></span></div></div><section class="panel"><h2 class="quiz-question">${esc(q.prompt)}</h2><div class="quiz-options">${q.options.map((v,i)=>`<button class="quiz-option ${quiz.choice!==null?(i===q.answer?'correct':i===quiz.choice?'wrong':''):''}" data-action="quiz-answer" data-index="${i}" ${quiz.choice!==null?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(v)}</button>`).join('')}</div>${quiz.choice!==null?`<div class="feedback ${quiz.choice===q.answer?'':'wrong'}" role="status"><strong>${quiz.choice===q.answer?esc(quiz.praise)+(quiz.combo>=3?` <span class="combo">🔥 ${quiz.combo} in a row!</span>`:''):'Almost! Mistakes are how princesses learn. 💗'}</strong><br>${esc(q.explanation)}</div>${action(quiz.index===l.questions.length-1?'See my result':'Next question '+icon('arrow'),'quiz-next')}`:''}</section></div>`;}
function finishQuiz(){const l=lessons.find(l=>l.id===quiz.id),pass=quiz.score>=Math.ceil(l.questions.length*.65),first=!state.completed[l.id];if(pass){state.completed[l.id]={score:quiz.score,total:l.questions.length,date:dayKey()};logActivity(state,first?30:5,first?l.duration:1);save();}
 main.innerHTML=`<div class="lesson-body panel completion"><div class="big-icon pop">${pass?(quiz.score===l.questions.length?'👑':'🌸'):'🌱'}</div><p class="eyebrow">${pass?(quiz.score===l.questions.length?'PERFECT SCORE, PRINCESS':'ONE STEP CLOSER'):'A LITTLE MORE PRACTICE'}</p><h1>${pass?`<span lang="el">Μπράβο, ${esc(greekName())}!</span> Lesson complete.`:`You’re getting there, ${esc(name())}.`}</h1><p>${quiz.score} of ${l.questions.length} correct. ${pass?'Your lesson is saved.':'Read the examples once more, then try again.'}</p><div>${pass?`<a class="btn primary" href="#lesson/${nextLesson().id}">Next lesson ${icon('arrow')}</a>`:action('Try again','start-quiz','primary',`data-id="${l.id}"`)}<a class="btn secondary" href="#lessons">All lessons</a></div><p class="center-note">${pass&&first?'+30 points 💖 · Progress saved on this device':''}</p></div>`;if(pass){const perfect=quiz.score===l.questions.length;setTimeout(()=>{rain(perfect?44:28);burstFrom($(".big-icon"),18);},60);}quiz=null;}
function phrasePage(){main.innerHTML=heading('Words for everyday life.',`${phrases.length} useful phrases. Tap to hear them, then make them yours.`,'YOUR POCKET PHRASEBOOK')+`<div class="toolbar"><div class="search-wrap">${icon('search')}<input id="phrase-search" type="search" placeholder="Search in English, Greek or Latin letters…" aria-label="Search phrases"></div><select id="phrase-category" aria-label="Filter phrases"><option value="all">All situations</option>${[...new Set(phrases.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><a class="btn secondary" href="#review">${icon('cards')} Review</a></div><div data-voice-status></div><div id="phrase-results" class="phrase-list"></div>`;filterPhrases();updateVoiceStatus();}
function fold(text){return String(text).normalize('NFD').replace(/[̀-ͯ]/g,'').toLocaleLowerCase();}
function filterPhrases(){const term=fold($('#phrase-search')?.value||''),cat=$('#phrase-category')?.value||'all';const found=phrases.filter(p=>(cat==='all'||cat===p.category)&&fold(`${p.el} ${p.tr} ${p.en}`).includes(term));$('#phrase-results').innerHTML=found.length?found.map(p=>`<article class="phrase-card"><div><div class="category">${esc(p.category)} ${levelBadge(p.level)}</div><strong lang="el">${esc(p.el)}</strong>${tr(p.tr)}<p>${esc(p.en)}</p>${p.note?`<small>${esc(p.note)}</small>`:''}</div><div class="phrase-actions">${sound(p.el)}<a class="sound-btn" href="#practice/${p.id}" aria-label="Practise this phrase: ${esc(p.el)}">${icon('mic')}</a></div></article>`).join(''):'<div class="empty">No phrases found. Try another word or situation.</div>';}
function reviewPage(){const list=activePhrases(),due=dueCards(list,state),seen=list.filter(p=>state.cards[p.id]).length,learning=due.filter(p=>state.cards[p.id]).length;
 main.innerHTML=heading('A few words, remembered.','Recall a phrase, reveal the answer, then rate how it felt.','SPACED REVIEW',`<span class="trip-chip">${due.length} ready · ${level()}</span>`)+`<div class="review-shell"><div class="panel completion"><div class="big-icon">${icon('cards')}</div><h2 class="completion-title">${due.length?'Keep your Greek close.':'You’re all caught up.'}</h2><p>${due.length?`${learning} previously reviewed · ${list.length-seen} new phrases`:'Your next reviews will appear when they’re due.'}</p><p class="center-note">${due.length?`A short session of up to 10 cards from the phrases up to ${level()}.`:'Come back tomorrow, or explore a lesson now.'}</p>${due.length?action('Start 10-card review '+icon('arrow'),'start-review'):'<a class="btn primary" href="#lessons">Explore lessons</a>'}</div><div class="notice">Say the Greek out loud before revealing it. “Again” returns in 1 minute; other ratings schedule the next review for 1 day or later. Change your level in Settings to include A2 phrases.</div></div>`;
}
function renderReview(){if(review.index>=review.cards.length){const count=review.cards.length;main.innerHTML=`<div class="review-shell panel completion"><div class="big-icon">🫒</div><p class="eyebrow">A LITTLE STRONGER THAN BEFORE</p><h1>Those words are staying with you.</h1><p>${count} cards reviewed. Your next reviews are scheduled.</p><a class="btn primary" href="#practice">Say something out loud ${icon('arrow')}</a>${action('Back to review','review-home','secondary')}<p class="center-note">If you chose Again, that card becomes due after 1 minute.</p></div>`;return;}
 const p=review.cards[review.index],toGreek=review.direction==='en';
 main.innerHTML=`<div class="review-shell">${heading('Make it stick.','','YOUR DAILY REVIEW')}<div class="review-controls"><span>Card ${review.index+1} / ${review.cards.length}</span><div class="toggle-group"><button class="toggle ${toGreek?'active':''}" data-action="review-direction" data-value="en">English → Greek</button><button class="toggle ${toGreek?'':'active'}" data-action="review-direction" data-value="el">Greek → English</button></div></div><div class="progress-track" style="margin-bottom:20px"><span style="width:${review.index/review.cards.length*100}%"></span></div><section class="review-card"><p class="eyebrow">${esc(p.category)} · ${toGreek?'SAY IT IN GREEK':'WHAT DOES THIS MEAN?'}</p>${toGreek?`<h2>${esc(p.en)}</h2>`:`<h2 lang="el">${esc(p.el)}</h2>${sound(p.el)}`}${review.flipped?(toGreek?`<p class="translation" lang="el">${esc(p.el)}</p>${tr(p.tr)}${sound(p.el)}`:`${tr(p.tr)}<p class="translation">${esc(p.en)}</p>`)+(p.note?`<p class="review-note">${esc(p.note)}</p>`:''):action('Reveal answer','flip-review','primary reveal')}</section>${review.flipped?`<div class="ratings">${[['again','Again'],['hard','Hard'],['good','Got it'],['easy','Easy']].map(([grade,title])=>{const next=schedule(state.cards[p.id],grade);return `<button class="rating" data-action="rate-review" data-grade="${grade}">${title}<small>${grade==='again'?'1 min':next.interval+' day'+(next.interval===1?'':'s')}</small></button>`;}).join('')}</div>`:'<p class="center-note" style="margin-top:23px">Pause, remember, say it. Then reveal.</p>'}<div data-voice-status></div></div>`;updateVoiceStatus();}
function practiceTabs(active){return `<div class="practice-tabs"><button class="btn ${active==='repeat'?'active':'secondary'}" data-action="practice-home">${icon('mic')} Listen & repeat</button><button class="btn ${active==='talk'?'active':'secondary'}" data-action="show-scenarios">${icon('chat')} Conversations</button></div>`;}
function practicePage(){const p=phrases[speakIndex%phrases.length];
 main.innerHTML=heading('Find your Greek voice.','Listen closely, repeat it, then try a short conversation.','SPEAKING PRACTICE')+practiceTabs('repeat')+`<div class="speaking-layout"><div><div class="panel speaking-card"><p class="eyebrow">${esc(p.category)} · LISTEN, THEN REPEAT</p><h2 lang="el">${esc(p.el)}</h2>${tr(p.tr)}<p>${esc(p.en)}</p><div class="listen-actions">${listenButton(p.el,false,'Listen')}${listenButton(p.el,true,'Slower')}</div><button class="microphone" data-action="start-speech" aria-label="Start speech recognition" ${Recognition?'':'disabled'}>${icon('mic')}</button><p class="mic-caption" id="mic-caption">${Recognition?'Tap the mic, then say the Greek phrase.':'Speech recognition is unavailable in this browser. Record yourself or practise aloud below.'}</p><div id="speech-result"></div><div class="button-row" style="justify-content:center">${action(icon('mic')+' Record & replay','record-audio','secondary small')}${action('I practised aloud '+icon('check'),'mark-spoken','secondary small')}${action('Next phrase '+icon('arrow'),'next-speech','secondary small')}</div><div id="recording-result"></div><div class="typed-practice"><label for="typed-practice">Prefer typing? Type it from memory, in Greek or in Latin letters.</label><div class="input-row"><input id="typed-practice" lang="el" autocomplete="off" placeholder="Γράψε εδώ… / grápse edhó…"><button class="btn secondary small" data-action="check-typed">Check</button></div></div></div><div data-voice-status></div><p class="speech-privacy">Microphone access is requested only when you tap a recording control. Browser speech recognition may send audio to its provider and need internet. Record & replay stays in memory on this device. Word matching is a practice aid, not an accent assessment.</p></div><aside class="panel"><h2>The sound of Greek</h2><div class="speaking-tips">${pronunciation.slice(0,3).map(t=>`<div class="tip-card"><h3>${esc(t.title)}</h3><p>${esc(t.tip)}</p><div class="tip-example"><span lang="el">${esc(t.el)}</span>${sound(t.el)}</div></div>`).join('')}</div><a class="text-link" href="#alphabet">More pronunciation tips ${icon('arrow')}</a></aside></div>`;updateVoiceStatus();}
function speakingCredit(id){const key=dayKey()+id;if(!sessionSpoken.has(key)){sessionSpoken.add(key);state.speaking++;logActivity(state,5,1);save();}}
function compareResult(text,typed=false){const p=phrases[speakIndex%phrases.length],score=bestMatch(typed?[p.el,p.tr]:[p.el],text);const good=score>=80;if(good&&!typed)speakingCredit(p.id);
 $('#speech-result').innerHTML=`<div class="speech-result" role="status"><strong>${good?esc(praise())+' Your words matched.':'A good start. Listen once more and try again.'}</strong><p>${typed?'You typed':'Your browser heard'}: “${esc(text)}”</p><p>Word match: ${score}%. ${typed?'Accents and capitals are ignored.':'This compares the transcript, not your accent.'}</p></div>`;if(good)burstFrom($('#speech-result .speech-result'),14);}
function startSpeech(targetId='practice'){
 if(!Recognition){toast('Use Record & replay, or practise aloud in this browser.');return;}
 if(recognition){recognition.stop();return;}
 if(recording?.state==='recording'){toast('Stop your replay recording first.');return;}
 player.stop();
 const r=new Recognition();recognition=r;r.lang=LOCALE;r.interimResults=false;r.maxAlternatives=3;r.continuous=false;
 const mic=targetId==='practice'?$('[data-action="start-speech"]'):$('[data-action="scenario-speech"]');mic?.classList.add('recording');if(targetId==='practice')$('#mic-caption').textContent='Listening… tap again to stop.';else if($('#scenario-status'))$('#scenario-status').textContent='Listening…';
 r.onresult=e=>{const text=e.results[0][0].transcript;if(targetId==='practice')compareResult(text);else{const input=$('#scenario-input');if(input)input.value=text;checkScenario(text,true);}};
 r.onerror=e=>{const messages={'not-allowed':'Microphone access was denied. Allow it in your browser settings, or use typed practice.','no-speech':'No speech was detected. Try again in a quieter spot.','network':'Speech recognition needs a working connection. Try Record & replay instead.','audio-capture':'No microphone was found. Try typed practice.','language-not-supported':'Your browser does not support Greek recognition. Try typed practice.'};const msg=messages[e.error]||'Speech recognition stopped. Try again or type your answer.';if(targetId==='practice'){if($('#mic-caption'))$('#mic-caption').textContent=msg;}else if($('#scenario-status'))$('#scenario-status').textContent=msg;};
 r.onend=()=>{if(recognition===r)recognition=null;mic?.classList.remove('recording');if(targetId==='practice'&&$('#mic-caption')?.textContent.startsWith('Listening'))$('#mic-caption').textContent='Tap the mic to try again.';};
 try{r.start();}catch{recognition=null;mic?.classList.remove('recording');toast('Could not start speech recognition. Use typed practice or record & replay.');}
}
async function recordAudio(){
 if(recording?.state==='recording'){recording.stop();return;}
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable. Try a supported browser on HTTPS or localhost.');return;}
 if(recognition){recognition.abort();recognition=null;}
 player.stop();const startRoute=route;
 try{
 const stream=await navigator.mediaDevices.getUserMedia({audio:true});
 if(route!==startRoute){stream.getTracks().forEach(t=>t.stop());return;}
 recordStream=stream;const chunks=[];const recorder=new MediaRecorder(stream);recording=recorder;const button=$('[data-action="record-audio"]');button.innerHTML=icon('stop')+' Stop recording';button.classList.add('recording');
 recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
 recorder.onstop=()=>{clearTimeout(recordTimeout);stream.getTracks().forEach(t=>t.stop());recordStream=null;recording=null;if(route!==startRoute)return;if(recordUrl)URL.revokeObjectURL(recordUrl);const blob=new Blob(chunks,{type:recorder.mimeType});recordUrl=URL.createObjectURL(blob);const box=$('#recording-result');if(box)box.innerHTML=`<p class="center-note">Your recording — listen, compare, try again.</p><audio controls src="${recordUrl}" style="width:100%;margin-top:10px"></audio>`;if(button?.isConnected){button.innerHTML=icon('mic')+' Record again';button.classList.remove('recording');}};
 // Exam answers run longer than single phrases.
 recorder.start();recordTimeout=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},route==='paper'?120000:15000);
 }catch{recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;toast('Microphone access is unavailable. Check browser permissions, or practise aloud.');}
}
function scenarioCard(s){return `<a href="#scenario/${s.id}" class="scenario-card"><div class="scenario-icon">${s.icon}</div><p class="eyebrow">${s.level} ${state.scenarios.includes(s.id)?'· PRACTISED':''}</p><h2>${esc(s.title)}</h2><p>${esc(s.subtitle)}</p><span class="text-link">Start the conversation ${icon('arrow')}</span></a>`;}
function scenariosPage(){main.innerHTML=heading('Short conversations. Real situations.','The same kind of role play as part C of the speaking exam.','CONVERSATIONS')+practiceTabs('talk')+`<div class="scenario-grid">${upToLevel(scenarios,'A2').map(scenarioCard).join('')}</div><div class="notice">These are guided role plays with model replies. Listen to the other person, then say or type your reply. You can reveal the model reply whenever you need it.</div>`;}
function scenarioPage(id){const scenario=scenarios.find(s=>s.id===id);if(!scenario){location.hash='practice';return;}if(!scenarioSession||scenarioSession.id!==id)scenarioSession={id,step:0,hint:false,checked:false};renderScenario();}
function turnHtml(t,label){return `<div class="chat-turn ${t.speaker==='you'?'you':''}"><div class="chat-label">${label}</div><div class="chat-line"><strong lang="el">${esc(t.el)}</strong>${sound(t.el)}</div>${tr(t.tr)}<p>${esc(t.en)}</p></div>`;}
function renderScenario(){const s=scenarios.find(s=>s.id===scenarioSession.id),pair=scenarioSession.step*2,them=s.turns[pair],you=s.turns[pair+1];
 if(!them||!you){if(!state.scenarios.includes(s.id)){state.scenarios.push(s.id);logActivity(state,20,3);save();}main.innerHTML=`<div class="conversation panel completion"><div class="big-icon pop">${s.icon}</div><p class="eyebrow">CONVERSATION PRACTISED</p><h1><span lang="el">Μπράβο, πριγκίπισσα!</span> One more conversation in the bag.</h1><p>You made it through “${esc(s.title)}”. Practise again any time, or swap roles with a friend.</p><a class="btn primary" href="#practice">Keep practising ${icon('arrow')}</a>${action('Try this conversation again','restart-scenario','secondary')}</div>`;rain(24);return;}
 main.innerHTML=`<div class="conversation"><a href="#practice" class="text-link back-link">${icon('back')} Practice</a>${heading(esc(s.title),esc(s.subtitle),`${s.level} · CONVERSATION`)}<div class="quiz-progress"><span>Exchange ${scenarioSession.step+1} / ${s.turns.length/2}</span><div class="progress-track"><span style="width:${pair/s.turns.length*100}%"></span></div></div>${s.turns.slice(0,pair).map(t=>turnHtml(t,t.speaker==='you'?'YOU':'THE OTHER PERSON')).join('')}${turnHtml(them,'THE OTHER PERSON')}<div class="chat-turn you"><div class="chat-label">YOUR TURN · SAY THIS IN GREEK</div><strong>${esc(you.en)}</strong>${scenarioSession.hint?`<p lang="el">Model reply: ${esc(you.el)}</p>${tr(you.tr)}${sound(you.el)}`:''}<div class="input-row"><input id="scenario-input" lang="el" placeholder="Η απάντησή σου…" autocomplete="off" aria-label="Your reply in Greek"><button class="btn secondary small" data-action="scenario-speech" ${Recognition?'':'disabled'} aria-label="Say your reply">${icon('mic')}</button>${action('Check reply','check-scenario','primary small')}</div><div id="scenario-status" class="small-status" role="status"></div></div><div class="chat-actions">${action('Show model reply','scenario-hint','secondary small')}${action(scenarioSession.step===s.turns.length/2-1?'Finish conversation '+icon('check'):'Next exchange '+icon('arrow'),'scenario-next','primary small',scenarioSession.checked?'':'disabled')}</div><p class="speech-privacy">Microphone recognition uses Greek (el-GR) and may send audio to your browser’s provider. Replies are compared with model sentences; other natural wording can also be correct.</p><div data-voice-status></div></div>`;updateVoiceStatus();}
function checkScenario(text,fromMic=false){const s=scenarios.find(s=>s.id===scenarioSession.id),t=s.turns[scenarioSession.step*2+1];if(!text.trim()){toast('Say or type a reply first.');return;}const score=bestMatch([t.el,t.tr,...(t.alternatives||[])],text);
 $('#scenario-status').textContent=score>=75?'Πολύ καλά! Your reply matches the model.':`Your words differ from the model (${score}% word match). Other replies can be valid. Reveal the model and compare, then continue.`;scenarioSession.checked=true;$('[data-action="scenario-next"]').disabled=false;if(score>=75&&fromMic)speakingCredit(s.id+scenarioSession.step);}
function paperResult(key){const r=state.exam[key];if(!r)return '<span class="muted">Not practised yet</span>';return `<span class="paper-score">Best: ${r.score} / ${r.total}${r.total>1?` · ${Math.round(r.score/r.total*100)}%`:''}</span>`;}
function levelToggle(target){return `<div class="toggle-group level-toggle" role="group" aria-label="Exam level">${LEVELS.map(l=>`<button class="toggle ${level()===l?'active':''}" data-action="set-level" data-value="${l}" data-target="${target}" aria-pressed="${level()===l}">${l}</button>`).join('')}</div>`;}
function examPage(){const ex=exam[level()];
 main.innerHTML=heading('Greek Language Certificate','Practise all four papers in the official A1 and A2 format.','EXAM PRACTICE',levelToggle('exam'))+`<section class="panel exam-overview"><div class="section-heading"><h2>${levelBadge(level())} ${esc(ex.name)}: how the exam works</h2><span>Written papers: ${esc(ex.writtenTotal)}</span></div><div class="exam-table" role="table"><div class="exam-row head" role="row"><span role="columnheader">Paper</span><span role="columnheader">Marks</span><span role="columnheader">Time</span><span role="columnheader">Tasks</span></div>${PAPERS.map(p=>{const pp=ex.papers[p];return `<div class="exam-row" role="row"><span role="cell"><strong>${esc(pp.title)}</strong></span><span role="cell">${pp.marks}</span><span role="cell">${pp.timeLabel||pp.minutes}${pp.perPair?' min per pair':' min'}</span><span role="cell"><ul>${pp.official.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></span></div>`;}).join('')}</div><p class="source-note">Structure from the official exam specification for ${level()} published by the Centre for the Greek Language. The speaking test is taken in pairs. In the writing paper you must not write your real name. Check dates, fees and current rules on <a href="${officialLinks.info}" target="_blank" rel="noopener">greek-language.gr/certification</a>.</p></section><div class="paper-grid">${PAPERS.map(p=>{const pp=ex.papers[p];return `<a class="task-card paper-card" href="#paper/${level()}-${p}"><div class="task-top"><span class="stat-icon">${icon(paperIcons[p])}</span><span class="task-time">${icon('clock')}${pp.minutes} min</span></div><h3>${esc(pp.title)}</h3><p>${paperResult(`${level()}-${p}`)}</p><div class="task-bottom"><span class="task-tag">${pp.tasks?pp.tasks.length+' TASKS':p==='speaking'?'3 PARTS':'2 PARTS'}</span><span class="arrow-circle">${icon('arrow')}</span></div></a>`;}).join('')}</div><div class="notice">These practice papers are written for this app in the official formats. They are not official exam papers. For real past samples with audio, see the <a href="${officialLinks.samples}" target="_blank" rel="noopener">official sample papers</a>. If you need the certificate for a residence permit, ask the authority handling your case which level and certificate they require.</div>`;}
function paperPage(key){const [lv,paper]=key.split('-');if(!exam[lv]||!PAPERS.includes(paper)){location.hash='exam';return;}
 if(lv!==level()){state.settings.level=lv;save();}
 const pp=exam[lv].papers[paper];
 const top=`<a class="text-link back-link" href="#exam">${icon('back')} Exam overview</a>`+heading(`${esc(pp.title)} · ${lv}`,`${pp.marks} marks · ${pp.minutes} minutes${pp.perPair?' per pair':''} in the real exam.`,'PRACTICE PAPER',paper==='reading'||paper==='listening'?`<span class="trip-chip" id="exam-timer" aria-live="off">${icon('clock')} ${pp.minutes}:00</span>`:'');
 if(paper==='writing')return writingPaper(lv,pp,top);
 if(paper==='speaking')return speakingPaper(lv,pp,top);
 if(!examSession||examSession.key!==key)examSession={key,answers:Object.fromEntries(pp.tasks.map(t=>[t.id,[]])),submitted:false,started:Date.now(),plays:{}};
 renderObjectivePaper(lv,paper,pp,top);
}
function itemInput(task,item,i){const chosen=examSession.answers[task.id][i],done=examSession.submitted,right=chosen===item.answer;
 const status=done?`<div class="item-feedback ${right?'':'wrong'}">${right?'✓ Correct':`✗ Answer: ${esc(item.options[item.answer])}`}${item.why?` · ${esc(item.why)}`:''}</div>`:'';
 const control=item.options.length>4?`<select data-exam-task="${task.id}" data-item="${i}" aria-label="Answer ${i+1}" ${done?'disabled':''}><option value="">Choose…</option>${item.options.map((o,j)=>`<option value="${j}" ${chosen===j?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<div class="exam-options" role="radiogroup">${item.options.map((o,j)=>`<label class="exam-option ${done&&j===item.answer?'correct':done&&j===chosen?'wrong':''}"><input type="radio" name="${task.id}-${i}" value="${j}" data-exam-task="${task.id}" data-item="${i}" ${chosen===j?'checked':''} ${done?'disabled':''}><span lang="el">${esc(o)}</span></label>`).join('')}</div>`;
 return `<div class="exam-item"><p class="exam-prompt"><span class="item-num">${i+1}</span><span lang="el">${esc(item.prompt)}</span></p>${control}${status}</div>`;}
function renderObjectivePaper(lv,paper,pp,top){const done=examSession.submitted;
 main.innerHTML=`<div class="paper-body">${top}${paper==='listening'?'<div class="notice">In the real exam you hear each recording twice. Press Play, listen without reading, then answer. Scripts appear after you check your answers.</div><div data-voice-status></div>':''}${pp.tasks.map(t=>`<section class="panel exam-task"><h2>${esc(t.title)}</h2><p class="muted">${esc(t.instructions)}</p>${t.text?`<div class="exam-text" lang="el">${esc(t.text)}</div>`:''}${t.items[0].options.length>4?`<ul class="option-bank" lang="el">${t.items[0].options.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>`:''}${t.script?`<div class="button-row"><button class="btn secondary small" data-action="play-script" data-task="${t.id}">${icon('play')} Play recording</button><span class="muted small-status">Plays: ${examSession.plays[t.id]||0} / 2</span></div>`:''}${done&&(t.textEn||t.script)?`<details class="exam-reveal" open><summary>${t.script?'Script and translation':'Translation'}</summary>${t.script?`<div class="exam-text" lang="el">${t.script.map(l=>`<p><strong>${esc(l.speaker)}:</strong> ${esc(l.el)}</p>`).join('')}</div>`:''}<p class="muted">${esc(t.textEn||t.scriptEn)}</p></details>`:''}<div class="exam-items">${t.items.map((item,i)=>itemInput(t,item,i)).join('')}</div></section>`).join('')}${done?paperSummary(lv,paper,pp):`<div class="panel completion">${action('Check my answers '+icon('check'),'submit-paper')}<p class="center-note">Unanswered questions count as wrong. You can retry afterwards.</p></div>`}</div>`;
 updateVoiceStatus();if(!done)startExamTimer(pp.minutes);
}
function paperSummary(lv,paper,pp){const scores=pp.tasks.map(t=>({t,score:scoreAnswers(t.items,examSession.answers[t.id]),total:t.items.length})),score=scores.reduce((s,x)=>s+x.score,0),total=scores.reduce((s,x)=>s+x.total,0),pct=Math.round(score/total*100),mins=Math.max(1,Math.round((examSession.finished-examSession.started)/60000));
 return `<section class="panel completion"><div class="big-icon pop">${pct>=90?'👑':pct>=70?'🏛️':pct>=50?'🌸':'🌱'}</div><p class="eyebrow">${lv} ${esc(pp.title.toUpperCase())} · PRACTICE RESULT</p><h1>${score} / ${total} correct (${pct}%)</h1><p>${scores.map(x=>`${esc(x.t.title.split('·')[0].trim())}: ${x.score}/${x.total}`).join(' · ')}</p><p class="center-note">Time used: about ${mins} min of ${pp.minutes}. This is practice scoring, not the official marking scale.</p><div class="button-row" style="justify-content:center">${action('Try again','retry-paper','secondary')}<a class="btn primary" href="#exam">Exam overview ${icon('arrow')}</a></div></section>`;}
function startExamTimer(minutes){clearInterval(examTimer);const end=examSession.started+minutes*60000;const tick=()=>{const n=$('#exam-timer');if(!n){clearInterval(examTimer);return;}const left=Math.round((end-Date.now())/1000),abs=Math.abs(left);n.innerHTML=`${icon('clock')} ${left<0?'+':''}${Math.floor(abs/60)}:${String(abs%60).padStart(2,'0')}${left<0?' over time':' left'}`;n.classList.toggle('over',left<0);};tick();examTimer=setInterval(tick,1000);}
function submitPaper(){const [lv,paper]=examSession.key.split('-'),pp=exam[lv].papers[paper];examSession.submitted=true;examSession.finished=Date.now();clearInterval(examTimer);
 const score=pp.tasks.reduce((s,t)=>s+scoreAnswers(t.items,examSession.answers[t.id]),0),total=pp.tasks.reduce((s,t)=>s+t.items.length,0),prev=state.exam[examSession.key];
 if(!prev||score/total>=prev.score/prev.total)state.exam[examSession.key]={score,total,date:dayKey()};logActivity(state,25,Math.min(pp.minutes,Math.round((examSession.finished-examSession.started)/60000)));save();paperPage(examSession.key);window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});if(score/total>=.7)setTimeout(()=>rain(score/total>=.9?44:26),400);}
function writingPaper(lv,pp,top){
 main.innerHTML=`<div class="paper-body">${top}<div class="notice">Write by hand if you can: the real exam is on paper. Use an invented name, never your own. Drafts are saved on this device.</div>${pp.tasks.map(t=>{const text=state.writing[t.id]?.text||'';return `<section class="panel exam-task"><p class="eyebrow">${esc(t.part)} · ABOUT ${t.words} WORDS</p><h2 lang="el">${esc(t.promptEl)}</h2><p>${esc(t.prompt)}</p><textarea class="writing-box" id="write-${t.id}" data-writing="${t.id}" lang="el" rows="8" placeholder="Γράψε εδώ…">${esc(text)}</textarea><p class="muted small-status"><span id="wc-${t.id}">${wordCount(text)}</span> words · target about ${t.words}</p><fieldset class="checklist"><legend>Self-check before you finish</legend>${t.checklist.map((c,i)=>`<label><input type="checkbox" data-check="${t.id}" value="${i}"> ${esc(c)}</label>`).join('')}</fieldset><details class="exam-reveal"><summary>Show a model answer</summary><div class="exam-text" lang="el">${esc(t.model.el)}</div>${listenButton(t.model.el,false,'Listen to the model')}<p class="muted">${esc(t.model.en)}</p></details></section>`;}).join('')}<div class="panel completion">${action('Save my self-check '+icon('check'),'save-writing')}<p class="center-note">Your self-check score is the number of checklist points you ticked. The official exam is marked by trained examiners.</p><p>${paperResult(`${lv}-writing`)}</p></div><div data-voice-status></div></div>`;updateVoiceStatus();}
function speakingPaper(lv,pp,top){
 main.innerHTML=`<div class="paper-body">${top}<div class="notice">The speaking test is taken in pairs, with no preparation time except about 2 minutes to read your role card in part C. Answer out loud, record yourself, then compare with the model.</div><div class="panel speaking-card"><p class="eyebrow">RECORD & REPLAY</p><p>Record up to 2 minutes, listen back, and try again.</p><div class="button-row" style="justify-content:center">${action(icon('mic')+' Record & replay','record-audio','secondary')}</div><div id="recording-result"></div></div><section class="panel exam-task"><h2>Part A · Questions about you</h2><p class="muted">Listen to each question and answer in one or two full sentences.</p>${pp.partA.map(q=>`<div class="example"><div><strong lang="el">${esc(q.el)}</strong>${tr(q.tr)}<p>${esc(q.en)}</p><details><summary>Model answer</summary><p lang="el">${esc(q.model)}</p></details></div>${sound(q.el)}</div>`).join('')}</section><section class="panel exam-task"><h2>Part B · Speak for about a minute</h2><p class="muted">Pick a topic. Use the prompts and speak without stopping.</p>${pp.partB.map(b=>`<div class="monologue"><h3 lang="el">${esc(b.title)} <span class="muted">· ${esc(b.en)}</span></h3><ul>${b.prompts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><details class="exam-reveal"><summary>Model answer</summary><div class="exam-text" lang="el">${esc(b.model)}</div>${listenButton(b.model,false,'Listen')}</details></div>`).join('')}</section><section class="panel exam-task"><h2>Part C · Role play</h2><p class="muted">In the exam you act out a situation with the other candidate. Practise these with the app, then with a friend taking the other role.</p><div class="scenario-grid">${pp.partC.map(id=>scenarioCard(scenarios.find(s=>s.id===id))).join('')}</div></section><div class="panel completion">${action('I practised the speaking paper '+icon('check'),'save-speaking')}<p>${state.exam[`${lv}-speaking`]?`Last practised ${esc(state.exam[`${lv}-speaking`].date)}`:''}</p></div><div data-voice-status></div></div>`;updateVoiceStatus();}
function progressPage(){const pts=totalPoints(),minutes=todayMinutes(),percent=Math.min(100,minutes/state.settings.goal*100),seen=reviewedCount(),cards=Object.values(state.cards);const now=new Date();const days=Array.from({length:7},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-6+i,12);return {key:dayKey(d),label:d.toLocaleDateString('en',{weekday:'short'}),points:state.activity[dayKey(d)]?.points||0};});const max=Math.max(10,...days.map(d=>d.points));
 const r=rankFor(pts);
 main.innerHTML=heading(`Look how far you’ve come, ${esc(name())}.`,'Every conversation starts with a little practice.','YOUR PROGRESS',examChip())+`<section class="panel crown-panel"><div class="section-heading"><h2>Your crowns</h2><span>${pts} points</span></div><div class="rank-ladder">${ranks.map((x,i)=>`<div class="rank-step ${i<r.index?'won':i===r.index?'current':'locked'}"><span class="rank-emoji">${i<=r.index?x.emoji:'🔒'}</span><strong>${esc(x.title)}</strong><small lang="el">${esc(x.el)}</small><small>${x.min} pts</small></div>`).join('')}</div>${r.next?`<div class="sparkle-track"><span style="width:${r.progress*100}%"></span></div><p class="goal-label">${r.next.min-pts} points to ${esc(r.next.title)} ${r.next.emoji}. Lessons give 30, papers 25, conversations 20, each review 3.</p>`:'<p class="goal-label">You wear the highest crown. Βασίλισσα! 👑</p>'}</section><section class="panel"><div class="section-heading"><h2>Your badges</h2><span>${Object.keys(state.badges).length} / ${badges.length} collected</span></div><div class="badge-grid">${badges.map(b=>{const got=state.badges[b.id];return `<div class="badge-tile ${got?'got':''}"><span class="badge-emoji">${got?b.emoji:'🔒'}</span><strong>${esc(b.title)}</strong><small>${got?`Won ${esc(got)}`:esc(b.desc)}</small></div>`;}).join('')}</div></section>`+`<div class="stats-row"><div class="stat"><span class="stat-icon">${icon('flame')}</span><div><strong>${streak(state.activity)} ${streak(state.activity)===1?'day':'days'}</strong><small>Current streak</small></div></div><div class="stat"><span class="stat-icon">${icon('spark')}</span><div><strong>${pts}</strong><small>Practice points earned</small></div></div><div class="stat"><span class="stat-icon">${icon('mic')}</span><div><strong>${state.speaking}</strong><small>Speaking practices logged</small></div></div></div><div class="progress-grid"><div><section class="panel"><h2>This week</h2><p>Practice points per day. Today’s activity counts toward your streak.</p><div class="activity-week" role="img" aria-label="${esc(days.map(d=>d.label+': '+d.points+' points').join(', '))}">${days.map((d,i)=>`<div class="activity-day ${i===6?'today':''}"><span class="points">${d.points}</span><span class="activity-bar" style="height:${Math.max(4,d.points/max*100)}px"></span><span>${d.label}</span></div>`).join('')}</div></section><section class="panel"><h2>Your toolkit</h2>${LEVELS.map(l=>{const list=lessons.filter(x=>x.level===l);return `<div class="mini-stat-row"><span>${l} lessons completed</span><strong>${completedCount(list)} / ${list.length}</strong></div>`;}).join('')}<div class="mini-stat-row"><span>Distinct phrases reviewed</span><strong>${seen} / ${phrases.length}</strong></div><div class="mini-stat-row"><span>Cards with a 7+ day review interval</span><strong>${cards.filter(c=>c.interval>=7).length}</strong></div><div class="mini-stat-row"><span>Conversations practised</span><strong>${state.scenarios.length} / ${scenarios.length}</strong></div><p class="source-note">Progress measures your activity, not an official level.</p></section><section class="panel"><h2>Exam practice</h2>${LEVELS.map(l=>PAPERS.map(p=>`<div class="mini-stat-row"><span>${l} ${esc(exam[l].papers[p].title.toLowerCase())}</span><strong>${state.exam[`${l}-${p}`]?(p==='speaking'?'Practised':`${state.exam[`${l}-${p}`].score} / ${state.exam[`${l}-${p}`].total}`):'—'}</strong></div>`).join('')).join('')}</section></div><div><section class="panel"><h2>Today’s goal</h2><div class="goal-box"><span>Estimated practice minutes</span><strong>${Math.round(minutes)} / ${state.settings.goal}</strong></div><div class="progress-track"><span style="width:${percent}%"></span></div><p class="goal-label">Minutes are estimates from completed activities. ${percent>=100?'Goal reached. Μπράβο, πριγκίπισσα! 🎯':'A few focused minutes go a long way.'}</p><a class="text-link" href="#today">Keep going ${icon('arrow')}</a></section><section class="panel"><h2>Your road to the certificate</h2>${phases.map((p,i)=>`<div class="phase"><span class="phase-num">${i+1}</span><div><small>${esc(p.when)}</small><h3>${esc(p.title)}</h3><p>${esc(p.focus)}</p></div></div>`).join('')}</section></div></div>`;}
function settingsPage(){main.innerHTML=heading('Make it yours.','Your level, your exam date, your Greek voice.','SETTINGS & AUDIO')+`<div class="settings-grid"><div><section class="panel"><h2>Hello, princess 👑</h2><div class="form-field"><label for="learner-name">Your name</label><input type="text" id="learner-name" maxlength="40" value="${esc(name())}" autocomplete="given-name"><small>Used for greetings and celebrations around the app.</small></div></section><section class="panel"><h2>Your goal</h2><div class="form-field"><label>Target level</label>${levelToggle('settings')}<small>A1 shows A1 phrases in review. A2 adds the A2 phrases and opens A2 exam practice by default.</small></div><div class="form-field"><label for="exam-date">Exam date</label><input type="date" id="exam-date" value="${state.settings.examDate}" min="2026-01-01" max="2040-12-31"><small>Optional. Check the next session and registration dates on <a href="${officialLinks.info}" target="_blank" rel="noopener">greek-language.gr</a>.</small></div><div class="form-field"><label for="daily-goal">Daily practice goal</label><select id="daily-goal">${[5,10,15,20,30].map(n=>`<option value="${n}" ${state.settings.goal===n?'selected':''}>${n} minutes a day</option>`).join('')}</select></div><div class="form-field"><label class="switch-row"><input type="checkbox" id="translit" ${state.settings.translit?'checked':''}> Show Latin transliteration under Greek</label><small>Helpful at the start. Turn it off once you can read Greek letters; the exam has none.</small></div></section><section class="panel"><h2>Your Greek voice</h2><p>Listening uses a Greek voice installed on your device. Natural pace keeps the rhythm; Slower gives you more time.</p>${hasRecordings()?`<div class="form-field"><label for="audio-source">Listening audio</label><select id="audio-source"><option value="recorded" ${state.settings.audioSource!=='device'?'selected':''}>Included Greek recordings</option><option value="device" ${state.settings.audioSource==='device'?'selected':''}>Device voice</option></select></div>`:''}<div data-voice-status></div><div class="form-field"><label>Listening pace</label><div class="playback-presets">${[['Natural',1],['Clear',.9],['Slow',.75]].map(([label,rate])=>`<button class="btn secondary small ${state.settings.rate===rate?'active':''}" data-action="playback-preset" data-rate="${rate}" aria-pressed="${state.settings.rate===rate}">${label}</button>`).join('')}</div></div><div class="form-field"><label for="speech-rate">Fine-tune the speed</label><div class="range-row"><input type="range" id="speech-rate" min="0.6" max="1.1" step="0.05" value="${state.settings.rate}"><output id="speed-value">${state.settings.rate.toFixed(2)}×</output></div></div><div class="form-field"><label for="voice-select">Device voice</label><select id="voice-select"></select></div><div class="button-row">${listenButton('Καλημέρα! Θα ήθελα έναν καφέ, παρακαλώ.',false,'Try the voice')}${action('Use recommended voice','recommended-voice','secondary small')}</div><details class="voice-details"><summary>No Greek voice? Install one</summary><p><strong>iPhone / iPad:</strong> Settings → Accessibility → Spoken Content (or Read & Speak) → Voices → Greek. Download Melina, Enhanced or Premium if offered, then reopen the app.</p><p><strong>Mac:</strong> System Settings → Accessibility → Spoken Content (or Read & Speak) → System voice → Manage voices → Greek.</p><p><strong>Android:</strong> Settings → Accessibility → Text-to-speech → Google speech engine → Install voice data → Greek.</p><p><strong>Windows:</strong> Settings → Time & language → Speech → Add voices → Greek. Chrome and Edge also offer online Greek voices.</p></details></section></div><div><section class="panel install-panel"><h2>Greek in your pocket</h2><p>Add Ellinika to your home screen for quick practice on the go.</p>${action(icon('download')+' Install Ellinika','install','primary')}<div id="offline-status" class="source-note">Checking offline availability…</div><p class="source-note">Lessons, phrasebook, review, exam papers and progress work offline once installed. Device voices usually work offline; speech recognition may need internet. Offline storage needs HTTPS or localhost.</p></section><section class="panel"><h2>Keep your progress</h2><p>Your lessons, reviews, exam scores and writing drafts are saved only in this browser. Export a backup to move them to another device.</p><div class="button-row">${action(icon('download')+' Export backup','export-progress','secondary small')}${action('Import backup','import-progress','secondary small')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><div id="import-confirm"></div><details><summary>Start fresh</summary><p>This removes your saved progress and settings from this browser.</p>${action('Reset progress…','reset-request','secondary small danger')}<div id="reset-confirm"></div></details></section><section class="panel"><h2>About</h2><p>Made with love for ${esc(name())} 💖, to learn Greek properly together and pass the certificate.</p><p>Ellinika is a personal Greek learning companion for A1 and A2, built on the structure of the Rumbo Spanish app: short lessons, spaced review, speaking practice and conversations, plus practice papers in the format of the Greek Language Certificate.</p><p>It is not affiliated with the Centre for the Greek Language. Practice scores are not official results.</p></section></div></div>`;renderVoiceOptions();updateVoiceStatus();updateOfflineStatus();}
function renderVoiceOptions(){const select=$('#voice-select');if(!select)return;const all=rankedVoices(voices),recommended=chooseVoice(voices);select.innerHTML=`<option value="">Automatic · best available Greek voice</option>`+all.map(v=>`<option value="${esc(v.voiceURI)}" ${state.settings.voice===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)} · ${esc(voiceQuality(v))}${v===recommended?' · recommended':''}</option>`).join('');if(!all.length)select.innerHTML='<option value="">No Greek voices available yet</option>';}
async function updateOfflineStatus(){const n=$('#offline-status');if(!n)return;if(!('serviceWorker'in navigator)){n.textContent='Offline storage is unavailable in this browser.';return;}try{const reg=await navigator.serviceWorker.getRegistration();n.textContent=reg?.active?'Offline app files are ready on this device.':'Offline files are preparing. Keep this page open briefly, then refresh.';}catch{n.textContent='Offline status could not be checked.';}}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ellinika-progress-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Backup exported. Keep it somewhere safe.');}
let pendingImport=null;
async function importProgress(file){if(!file)return;if(file.size>2*1024*1024){toast('Choose an Ellinika JSON backup smaller than 2 MB.');return;}try{pendingImport=validateState(JSON.parse(await file.text()));$('#import-confirm').innerHTML=`<div class="danger-box">Replace this device’s progress with the backup? It contains ${Object.keys(pendingImport.completed).length} completed lessons and ${Object.keys(pendingImport.cards).length} reviewed phrases.<div class="button-row">${action('Use this backup','confirm-import','primary small')}${action('Cancel','cancel-import','secondary small')}</div></div>`;}catch{pendingImport=null;toast('Could not read this backup. Choose a valid Ellinika JSON export.');}}
function showInstall(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>installPrompt=null);return;}$('#help-content').innerHTML='<ol><li><strong>iPhone or iPad:</strong> open the app in Safari, tap Share, then Add to Home Screen.</li><li><strong>Android:</strong> open it in Chrome, tap the menu, then Install app or Add to Home screen.</li><li><strong>Computer:</strong> look for the install button in your browser’s address bar or menu.</li></ol>';$('#help-dialog').showModal();}
function cleanup(){recognition?.abort();recognition=null;clearTimeout(recordTimeout);clearInterval(examTimer);if(recording?.state==='recording'){recording.onstop=null;recording.stop();}recording=null;recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl='';}player.stop();}
function navigate(){cleanup();quiz=null;review=null;const parts=location.hash.replace(/^#\/?/,'').split('/');route=parts[0]||'today';sub=parts[1]||'';if(route!=='scenario')scenarioSession=null;if(route!=='paper')examSession=null;
 const render={today:todayPage,lessons:lessonsPage,alphabet:alphabetPage,phrases:phrasePage,review:reviewPage,practice:practicePage,exam:examPage,progress:progressPage,settings:settingsPage};if(route==='lesson')lessonPage(sub);else if(route==='scenario')scenarioPage(sub);else if(route==='paper')paperPage(sub);else if(render[route]){if(route==='practice'&&sub){const index=phrases.findIndex(p=>p.id===sub);if(index>=0)speakIndex=index;}render[route]();}else{location.hash='today';return;}
 document.title=`${route==='today'?`Ellinika for ${name()}`:route==='lesson'?'Lesson':route==='scenario'?'Conversation':route==='paper'?'Practice paper':route==='alphabet'?'Alphabet':nav.find(n=>n[0]===route)?.[2]||'Settings'} · Greek A1–A2`;updateChrome();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}

// One event handler keeps controls usable after each view refresh.
document.addEventListener('click',async e=>{
 const link=e.target.closest('a[href^="#"]');if(link?.classList.contains('skip')){e.preventDefault();main.focus();return;}if(link&&link.hash===location.hash){e.preventDefault();navigate();return;}
 const btn=e.target.closest('[data-say],[data-action]');if(!btn||btn.disabled)return;
 if(btn.dataset.say){say(decodeURIComponent(btn.dataset.say),btn.dataset.slow==='true',btn);return;}
 const a=btn.dataset.action;
 if(a==='playback-preset')setPlaybackRate(Number(btn.dataset.rate));
 else if(a==='recommended-voice'){state.settings.voice='';state.settings.audioSource='recorded';setPlaybackRate(NATURAL_RATE);renderVoiceOptions();updateVoiceStatus();say('Καλημέρα! Θα ήθελα έναν καφέ, παρακαλώ.',false,btn);}
 else if(a==='set-level'){state.settings.level=btn.dataset.value;save();if(btn.dataset.target==='settings')settingsPage();else examPage();}
 else if(a==='start-quiz'){quiz={id:btn.dataset.id,index:0,score:0,choice:null};renderQuiz();}
 else if(a==='quiz-answer'&&quiz&&quiz.choice===null){quiz.choice=Number(btn.dataset.index);const l=lessons.find(l=>l.id===quiz.id),right=quiz.choice===l.questions[quiz.index].answer;if(right){quiz.score++;quiz.combo=(quiz.combo||0)+1;quiz.praise=praise();}else quiz.combo=0;renderQuiz();if(right)burstFrom($(".quiz-option.correct"),quiz.combo>=3?22:12);else $(".quiz-option.wrong")?.classList.add("shake");}
 else if(a==='quiz-next'&&quiz){quiz.index++;quiz.choice=null;renderQuiz();}
 else if(a==='start-review'){review={cards:dueCards(activePhrases(),state).slice(0,10),index:0,flipped:false,direction:'en'};renderReview();}
 else if(a==='flip-review'&&review){review.flipped=true;renderReview();}
 else if(a==='review-direction'&&review){review.direction=btn.dataset.value;review.flipped=false;renderReview();}
 else if(a==='rate-review'&&review?.flipped){const p=review.cards[review.index];state.cards[p.id]=schedule(state.cards[p.id],btn.dataset.grade);logActivity(state,3,.5,true);const good=['good','easy'].includes(btn.dataset.grade);review.combo=good?(review.combo||0)+1:0;if(good)burstFrom(btn,review.combo>=5?18:8);save();review.index++;review.flipped=false;renderReview();if(review.combo>=3&&review.index<review.cards.length)toast(`🔥 ${review.combo} in a row, princess!`);}
 else if(a==='review-home'){review=null;reviewPage();}
 else if(a==='start-speech')startSpeech();
 else if(a==='next-speech'){cleanup();speakIndex=(speakIndex+1)%phrases.length;practicePage();}
 else if(a==='check-typed'){const text=$('#typed-practice').value.trim();if(text)compareResult(text,true);else toast('Type the Greek phrase first.');}
 else if(a==='mark-spoken'){speakingCredit(phrases[speakIndex%phrases.length].id);toast('Speaking practice logged. Μπράβο, πριγκίπισσα! 🎤');}
 else if(a==='record-audio')await recordAudio();
 else if(a==='practice-home'){cleanup();practicePage();}
 else if(a==='show-scenarios'){cleanup();scenariosPage();}
 else if(a==='scenario-speech')startSpeech('scenario');
 else if(a==='check-scenario')checkScenario($('#scenario-input').value);
 else if(a==='scenario-hint'){scenarioSession.hint=true;scenarioSession.checked=true;renderScenario();}
 else if(a==='scenario-next'&&scenarioSession?.checked){cleanup();scenarioSession.step++;scenarioSession.hint=false;scenarioSession.checked=false;renderScenario();window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'});}
 else if(a==='restart-scenario'){scenarioSession.step=0;scenarioSession.hint=false;scenarioSession.checked=false;renderScenario();}
 else if(a==='play-script'&&examSession){const [lv,paper]=examSession.key.split('-'),t=exam[lv].papers[paper].tasks.find(t=>t.id===btn.dataset.task);examSession.plays[t.id]=(examSession.plays[t.id]||0)+1;const label=btn.nextElementSibling;if(label)label.textContent=`Plays: ${examSession.plays[t.id]} / 2${examSession.plays[t.id]>2?' · more than in the exam':''}`;sayAll(t.script.map(l=>l.el),btn);}
 else if(a==='submit-paper'&&examSession&&!examSession.submitted)submitPaper();
 else if(a==='retry-paper'&&examSession){const key=examSession.key;examSession=null;paperPage(key);window.scrollTo({top:0,behavior:'instant'});}
 else if(a==='save-writing'){const lv=sub.split('-')[0],boxes=$$('[data-check]');const score=boxes.filter(b=>b.checked).length;state.exam[`${lv}-writing`]={score,total:boxes.length,date:dayKey()};logActivity(state,25,exam[lv].papers.writing.minutes/2);save();toast(`Self-check saved: ${score} of ${boxes.length} points ticked.`);paperPage(sub);}
 else if(a==='save-speaking'){const lv=sub.split('-')[0];state.exam[`${lv}-speaking`]={score:1,total:1,date:dayKey()};state.speaking++;logActivity(state,20,10);save();toast('Speaking practice saved. Μπράβο, πριγκίπισσα! 🎤');paperPage(sub);}
 else if(a==='export-progress')exportProgress();
 else if(a==='import-progress')$('#import-file').click();
 else if(a==='confirm-import'&&pendingImport){state=pendingImport;pendingImport=null;save();settingsPage();toast('Backup imported. Your progress is back.');}
 else if(a==='cancel-import'){pendingImport=null;$('#import-confirm').innerHTML='';}
 else if(a==='reset-request')$('#reset-confirm').innerHTML=`<div class="danger-box">Clear all lessons, reviews, exam scores and settings on this device?<div class="button-row">${action('Yes, clear my progress','reset-confirm','secondary small danger')}${action('Cancel','cancel-reset','secondary small')}</div></div>`;
 else if(a==='cancel-reset')$('#reset-confirm').innerHTML='';
 else if(a==='reset-confirm'){state=initialState();sessionSpoken.clear();save();settingsPage();toast('Progress reset on this device.');}
 else if(a==='install')showInstall();
 else if(a==='close-help')$('#help-dialog').close();
 else if(a==='close-party')$('#party').classList.remove('visible');
 else if(a==='open-note'&&!btn.classList.contains('open')){btn.classList.add('open');btn.setAttribute('aria-label','Today’s note');burstFrom(btn.querySelector('.envelope'),16);}
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='phrase-search')filterPhrases();if(t.id==='speech-rate')setPlaybackRate(Number(t.value));
 if(t.dataset.writing){const id=t.dataset.writing;$(`#wc-${id}`).textContent=wordCount(t.value);clearTimeout(writingTimer);writingTimer=setTimeout(()=>{state.writing[id]={text:t.value.slice(0,5000),date:dayKey()};save();},500);}});
document.addEventListener('change',e=>{const t=e.target;
 if(t.dataset.examTask&&examSession&&!examSession.submitted){const v=t.value===''?undefined:Number(t.value);examSession.answers[t.dataset.examTask][Number(t.dataset.item)]=v;return;}
 if(t.id==='phrase-category')filterPhrases();else if(t.id==='exam-date'){if(t.value===''){state.settings.examDate='';save();return;}if(!validDay(t.value)||t.value<'2026-01-01'||t.value>'2040-12-31'){toast('Choose a valid exam date.');t.value=state.settings.examDate;return;}state.settings.examDate=t.value;save();}else if(t.id==='daily-goal'){state.settings.goal=Number(t.value);save();}else if(t.id==='translit'){state.settings.translit=t.checked;save();}else if(t.id==='learner-name'){state.settings.name=t.value.trim().slice(0,40)||'Sana';t.value=state.settings.name;save();toast(`Γεια σου, ${greekName()}! 💖`);}else if(t.id==='audio-source'){player.stop();state.settings.audioSource=t.value;save();updateVoiceStatus();}else if(t.id==='voice-select'){state.settings.voice=t.value;save();updateVoiceStatus();}else if(t.id==='import-file')importProgress(t.files?.[0]);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset?.action==='open-note'){e.preventDefault();e.target.click();}if(e.key==='Enter'&&e.target.id==='typed-practice')$('[data-action="check-typed"]').click();if(e.key==='Enter'&&e.target.id==='scenario-input')$('[data-action="check-scenario"]').click();});
window.addEventListener('hashchange',navigate);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('pagehide',cleanup);
window.addEventListener('offline',()=>toast('You’re offline. Lessons, reviews and papers stay with you.'));
window.speechSynthesis?.addEventListener('voiceschanged',loadVoices);
loadVoices();navigate();loadVoicePack();
// Progress made before rewards existed still counts: celebrate it once on the first visit.
if(Object.values(state.activity).length){const before=Object.keys(state.badges).length;rewardCheck();const now=Object.keys(state.badges).length;if(now>before){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{}setTimeout(()=>party({emoji:'👑',eyebrow:'WELCOME BACK, PRINCESS',title:`${now-before} badges already earned!`,text:`Your progress is all here, ${name()}. Every lesson you finished still counts.`,link:'#progress'}),700);if(route==='today')todayPage();}}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.active)updateOfflineStatus();else reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',updateOfflineStatus);});}).catch(()=>{if(route==='settings')$('#offline-status').textContent='Offline files could not be installed. Use HTTPS or localhost and try reloading.';});
